var GIF={"A": "data:image/gif;base64,", "B": "data:image/gif;base64,", "C": "data:image/gif;base64,"};
var N={
1:{lv:1,t:"La Huida en el Espejo Oscuro",x:"Corre la medianoche en Hawkins. Has logrado escapar del monstruo en tu bicicleta, pero al llegar a tu casa descubres que todo está cubierto de una extraña bruma cenicienta, las paredes respiran y la atmósfera es helada: estás en el Upside Down. En el mundo real, las luces parpadean tenuemente, pero aquí afuera los rugidos de la criatura se escuchan cada vez más cerca. Tienes que decidir tu primera estrategia de supervivencia de inmediato.",q:"¿Qué decisión toma Will para ponerse a salvo?",c:[["Correr hacia el refugio de su infancia en el bosque: Castle Byers",2,"A"],["Entrar a su casa e intentar usar el teléfono fijo o las luces para comunicarse",3,"B"],["Buscar un arma o herramienta defensiva en el cobertizo de herramientas",4,"C"]]},
2:{lv:2,t:"El Camino a Castle Byers",x:"Te adentras en el bosque oscuro esquivando raíces gigantes y esporas flotantes que queman el aire. Divisas la estructura de madera de Castle Byers a lo lejos, pero las pisadas pesadas del Demogorgon resuenan a tus espaldas, cortando las ramas.",q:"¿Cómo abordas los últimos metros hacia el fuerte?",c:[["Avanzar muy lento y ocultarse sigilosamente entre los matorrales",5],["Correr a toda velocidad y encerrarse de un golpe dentro del fuerte",6]]},
3:{lv:2,t:"La Conexión con el Mundo Real",x:"Logras cruzar hacia la sala de tu casa en el Upside Down. El teléfono fijo está cubierto de baba, pero emite una estática extraña. Al mismo tiempo, las luces de Navidad de la pared parpadean intensamente como si alguien las estuviera tocando desde el otro lado.",q:"¿Cómo intentas pedir ayuda?",c:[["Levantar el auricular del teléfono fijo y gritar pidiendo auxilio",7],["Tocar las bombillas de las luces de Navidad para enviar una señal lumínica",8]]},
4:{lv:2,t:"El Cobertizo y las Armas",x:"Te refugias en el cobertizo de herramientas de la familia Byers. En la oscuridad, buscas a tientas algo que sirva para defenderte de la criatura que está a punto de tirar la puerta abajo.",q:"¿Qué decides empuñar para enfrentar al peligro?",c:[["Tomar el viejo rifle de caza de su padre y cargar los cartuchos",9],["Agarrar un cuchillo de cocina afilado y prepararse para la emboscada",10]]},
5:{lv:3,t:"Oculto en Castle Byers",x:"Will llega oculto a Castle Byers. A través de las rendijas del fuerte, ve pasar al Demogorgon olfateando el aire muy cerca.",q:"¿Qué hace Will?",c:[["Quedarse en completo silencio bajo una manta oscura",11],["Asomarse por la ventana para ver hacia dónde se dirige el monstruo",12]]},
6:{lv:3,t:"El Fuerte Cede",x:"Will llega corriendo, pero sus pisadas ruidosas alertan al monstruo, cuyas garras empiezan a destrozar los tablones de madera del fuerte.",q:"¿Qué hace Will?",c:[["Esconderse rápidamente en un hueco bajo el piso de madera",11],["Salir del fuerte y volver a correr hacia la niebla densa",12]]},
7:{lv:3,t:"La Voz de Joyce",x:"La estática inunda la línea. Logras percibir la voz de Joyce, pero el ruido ensordecedor atrae a la criatura, que entra rompiendo la pared de la sala.",q:"¿Qué hace Will?",c:[["Soltar el teléfono y esconderse dentro del armario de la despensa",12],["Lanzarle un frasco pesado a la cara para distraerlo y correr a la puerta",13]]},
8:{lv:3,t:"Las Luces Responden",x:"Joyce reconoce el parpadeo de las luces y golpea la pared con un hacha desde el mundo real. El estruendo confunde al Demogorgon.",q:"¿Qué hace Will?",c:[["Aprovechar la distracción y salir corriendo por la puerta trasera",13],["Quedarse paralizado esperando que su madre rompa la pared por completo",12]]},
9:{lv:3,t:"El Rifle No Alcanza",x:"Will dispara el rifle, pero las balas rebotan en la piel del Demogorgon sin hacerle daño. El monstruo abre su rostro lleno de dientes.",q:"¿Qué hace Will?",c:[["Usar la culata del arma para golpearlo en la cabeza e intentar huir",13],["Intentar recargar apresuradamente para disparar un segundo tiro",12]]},
10:{lv:3,t:"El Cuchillo Falla",x:"El monstruo bloquea el ataque con el cuchillo y desarma a Will de un golpe, acorralándolo contra los muebles de la cocina.",q:"¿Qué hace Will?",c:[["Hacerse el muerto en el suelo para que la criatura pierda el interés",12],["Deslizarse rápidamente por debajo de la mesa hacia el pasillo oscuro",11]]},
11:{lv:4,end:"open",t:"Supervivencia Temporal",tag:"FINAL ABIERTO",cond:"Alcanzado mediante decisiones de sigilo, ocultamiento y reflejos cautelosos.",x:"Will logra eludir al Demogorgon temporalmente y encuentra un rincón seguro donde esconderse en el Upside Down. Sabe que sigue atrapado en la pesadilla, pero su astucia le ha ganado un tiempo vital mientras sus amigos buscan la forma de rescatarlo."},
12:{lv:4,end:"fatal",t:"Atrapado en la Oscuridad",tag:"FINAL FATAL",cond:"Alcanzado al dudar, hacer ruido innecesario, ser acorralado o cometer errores tácticos.",x:"Las opciones fallidas exponen la posición de Will. El Demogorgon lo intercepta en la oscuridad, cerrando su trampa sobre él. La misión en el Upside Down termina de forma trágica."},
13:{lv:4,end:"good",t:"Ecos de Esperanza",tag:"FINAL BUENO",cond:"Alcanzado al aprovechar distracciones inteligentes (luces, objetos o golpes tácticos) para escapar del peligro inminente.",x:"Will logra burlar a la criatura y establecer un contacto directo y claro con el mundo real. Su madre y sus amigos ahora tienen la pista definitiva para abrir el portal y comenzar el rescate."}
};
var path=[1],app=document.getElementById('app'),bar=document.getElementById('bar'),trail=document.getElementById('trail');
function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;')}
function render(){
  var id=path[path.length-1],n=N[id],h='';
  var lvl=['','Nivel 1 · Planteamiento','Nivel 2 · Acción táctica','Nivel 3 · Reacción y consecuencias','Nivel 4 · Resolución'][n.lv];
  if(n.end){
    h='<div class="card end '+n.end+'"><h2>'+esc(n.t)+'</h2><span class="tag">'+n.tag+'</span><p class="cond" style="margin-top:14px">'+esc(n.cond)+'</p><p>'+esc(n.x)+'</p></div>';
  }else{
    h='<div class="card"><h2>'+esc(n.t)+'</h2><p>'+esc(n.x)+'</p><p class="q">'+esc(n.q)+'</p><div class="opts">';
    n.c.forEach(function(c,i){h+='<button'+(c[2]?' class="has"':'')+' data-to="'+c[1]+'">'+(c[2]?'<img class="gif" src="'+GIF[c[2]]+'" alt="">':'')+'<span class="txt"><span class="k">'+String.fromCharCode(65+i)+'</span>'+esc(c[0])+'</span></button>'});
    h+='</div></div>';
  }
  app.innerHTML=h;
  app.querySelectorAll('button').forEach(function(b){b.onclick=function(){path.push(+b.dataset.to);render();window.scrollTo({top:0,behavior:'smooth'})}});
  bar.innerHTML='';
  if(path.length>1){addBtn('← Volver un paso',function(){path.pop();render()});addBtn('↺ Reiniciar',function(){path=[1];render()})}
  trail.textContent='Recorrido: '+path.map(function(p){return 'Nodo '+p}).join(' → ');
}
function addBtn(t,f){var b=document.createElement('button');b.textContent=t;b.onclick=f;bar.appendChild(b)}
render();